#define LIBSSH_STATIC 1
#include <libssh/libssh.h>
#include <libssh/buffer.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <poc_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        perror("fopen");
        return 1;
    }
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    unsigned char *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    ssh_buffer buf = ssh_buffer_new();
    if (!buf) {
        fprintf(stderr, "Failed to create buffer\n");
        return 1;
    }

    ssh_buffer_add_data(buf, data, size);

    uint32_t val32;
    uint16_t val16;
    uint8_t val8;
    char *cstring = NULL;
    ssh_string str = NULL;
    void *pdata = NULL;
    size_t plen = 0;

    const char *formats[] = {
        "s", "S", "b", "w", "d", "q", "P",
        "bs", "ws", "ds", "bS", "dS", "bd", "db",
        "ss", "dds", "ddd", "sS", "Sb",
        NULL
    };

    for (int i = 0; formats[i] != NULL; i++) {
        ssh_buffer buf2 = ssh_buffer_new();
        ssh_buffer_add_data(buf2, data, size);

        int rc;
        if (strcmp(formats[i], "s") == 0) {
            rc = ssh_buffer_unpack(buf2, "s", &cstring);
            if (rc == SSH_OK) { free(cstring); cstring = NULL; }
        } else if (strcmp(formats[i], "S") == 0) {
            rc = ssh_buffer_unpack(buf2, "S", &str);
            if (rc == SSH_OK && str) { ssh_string_free(str); str = NULL; }
        } else if (strcmp(formats[i], "b") == 0) {
            rc = ssh_buffer_unpack(buf2, "b", &val8);
        } else if (strcmp(formats[i], "w") == 0) {
            rc = ssh_buffer_unpack(buf2, "w", &val16);
        } else if (strcmp(formats[i], "d") == 0) {
            rc = ssh_buffer_unpack(buf2, "d", &val32);
        } else if (strcmp(formats[i], "q") == 0) {
            uint64_t val64;
            rc = ssh_buffer_unpack(buf2, "q", &val64);
        } else if (strcmp(formats[i], "P") == 0) {
            plen = size;
            rc = ssh_buffer_unpack(buf2, "P", plen, &pdata);
            if (rc == SSH_OK) { free(pdata); pdata = NULL; }
        } else if (strcmp(formats[i], "bs") == 0) {
            rc = ssh_buffer_unpack(buf2, "bs", &val8, &cstring);
            if (rc == SSH_OK) { free(cstring); cstring = NULL; }
        } else if (strcmp(formats[i], "ws") == 0) {
            rc = ssh_buffer_unpack(buf2, "ws", &val16, &cstring);
            if (rc == SSH_OK) { free(cstring); cstring = NULL; }
        } else if (strcmp(formats[i], "ds") == 0) {
            rc = ssh_buffer_unpack(buf2, "ds", &val32, &cstring);
            if (rc == SSH_OK) { free(cstring); cstring = NULL; }
        } else if (strcmp(formats[i], "bS") == 0) {
            rc = ssh_buffer_unpack(buf2, "bS", &val8, &str);
            if (rc == SSH_OK) { ssh_string_free(str); str = NULL; }
        } else if (strcmp(formats[i], "dS") == 0) {
            rc = ssh_buffer_unpack(buf2, "dS", &val32, &str);
            if (rc == SSH_OK) { ssh_string_free(str); str = NULL; }
        } else if (strcmp(formats[i], "bd") == 0) {
            rc = ssh_buffer_unpack(buf2, "bd", &val8, &val32);
        } else if (strcmp(formats[i], "db") == 0) {
            rc = ssh_buffer_unpack(buf2, "db", &val32, &val8);
        } else if (strcmp(formats[i], "ss") == 0) {
            rc = ssh_buffer_unpack(buf2, "ss", &cstring, &cstring);
            if (rc == SSH_OK) { free(cstring); cstring = NULL; }
        } else if (strcmp(formats[i], "dds") == 0) {
            rc = ssh_buffer_unpack(buf2, "dds", &val32, &val32, &cstring);
            if (rc == SSH_OK) { free(cstring); cstring = NULL; }
        } else if (strcmp(formats[i], "ddd") == 0) {
            rc = ssh_buffer_unpack(buf2, "ddd", &val32, &val32, &val32);
        } else if (strcmp(formats[i], "sS") == 0) {
            rc = ssh_buffer_unpack(buf2, "sS", &cstring, &str);
            if (rc == SSH_OK) { free(cstring); ssh_string_free(str); cstring = NULL; str = NULL; }
        } else if (strcmp(formats[i], "Sb") == 0) {
            rc = ssh_buffer_unpack(buf2, "Sb", &str, &val8);
            if (rc == SSH_OK) { ssh_string_free(str); str = NULL; }
        }

        ssh_buffer_free(buf2);
    }

    ssh_buffer_free(buf);
    free(data);
    printf("All tests passed without crash\n");
    return 0;
}
